(()=>{'use strict';
 const M=BudgetDefence,$=id=>document.getElementById(id),screen=$('screen'),events=new AbortController();
 let state=M.create({reduced:matchMedia('(prefers-reduced-motion: reduce)').matches}),raf=0,last=0,audio=null,aim={x:500,y:230},shotUntil=0,closed=false,renderedPhase='';screen.tabIndex=-1;
 const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const on=(target,type,fn,options={})=>target.addEventListener(type,fn,{...options,signal:events.signal});
 const button=(label,action,extra='')=>`<button data-action="${action}" ${extra}>${label}</button>`;
 function syncLoop(){if(state.phase==='playing'&&!raf){last=performance.now();raf=requestAnimationFrame(frame)}else if(state.phase!=='playing'){cancelAnimationFrame(raf);raf=0;last=0}}
 function send(action){const before=state;state=M.act(state,action);if(state===before)return;if(action.type==='fire'&&state.shots!==before.shots||action.type==='fire'&&state.practice&&state.ammo!==before.ammo){shotUntil=performance.now()+140;sound()};render();syncLoop()}
 function frame(now){raf=0;if(closed||state.phase!=='playing')return;const previous=state.phase;state=M.act(state,{type:'tick',ms:Math.max(0,now-last)});last=now;if(previous!==state.phase)render();else {hud();draw()};if(state.phase==='playing')raf=requestAnimationFrame(frame);else last=0}
 function sound(){if(state.muted||closed)return;try{if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=390;g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.075);o.connect(g);g.connect(audio.destination);o.onended=()=>{o.disconnect();g.disconnect()};o.start();o.stop(audio.currentTime+.08)}catch{}}
 function reviews(){return state.targets.map(t=>`<div class="review"><strong>${t.correct?'✓':t.resolved?'↻':'○'} ${escape(t.cue)}</strong><p>${t.kind==='check'?escape(t.info)+' ':''}${escape(t.why)}</p></div>`).join('')}
 function render(){
  const focused=document.activeElement?.id,phase=state.phase;document.body.classList.toggle('no-motion',state.reduced);$('mute').checked=state.muted;$('motion').checked=state.reduced;$('feedback').textContent=state.feedback;
  if(phase==='instructions')screen.innerHTML=`<section class="panel instructions"><h2>保留資源，先查證。</h2><p>阿俊嘅帳單提醒我哋：反應快唔代表決定好。呢度係獨立訓練，冇故事獎金、冇抽箱。</p><ol><li>三輪，每輪三個非人形標靶。共用 <b>900 點器材預算</b>，每輪唔會補充。</li><li>可疑交易：<b>射擊拒絕</b>。已核實交易：<b>保護</b>。資料未明：<b>先查證</b>，讀完先決定。</li><li>每輪 45 秒；可隨時暫停，或開始前揀不限時。射得準同金融判斷分開顯示。</li><li>滑鼠／觸控：撳標靶射擊；先撳下面文字卡揀目標，再用「保護」或「查證」。鍵盤：Tab 揀文字卡、Enter 選取；1–3 揀標靶，X 射擊，G 保護，I 查證，R 換彈，P 暫停。畫布上亦可用方向鍵瞄準、空白射擊。</li></ol><label><input id="untimed" type="checkbox" ${state.untimed?'checked':''}> 無障礙不限時版（相同九個情境、相同評分，可全程用文字卡同鍵盤）</label><div class="actions">${button('先練習一次（唔計分）','practice')}${button('開始三輪挑戰','begin')}</div></section>`;
  else if(phase==='buy')screen.innerHTML=`<section class="panel"><div class="hud"><h2>第 ${state.round+1}／3 輪 · 購買階段</h2><strong>剩餘 ${state.credits}／900 點</strong></div><p>借用練習器免費：3 發、1.8 秒換彈。器材只限今輪，唔退款；今輪最多一款標記器加一張時間卡。</p><div class="cards">${Object.entries(M.equipment).map(([key,item])=>`<article class="card"><h3>${item.name}</h3><p>${item.detail}</p><strong>${item.cost} 點</strong>${button(state.purchases.includes(key)?'已購買':state.credits<item.cost?'預算不足':key==='reserve'&&state.untimed?'不限時唔需要':'購買','buy',`data-item="${key}" ${state.purchases.includes(key)||state.credits<item.cost||(key==='reserve'?(state.aid||state.untimed):state.weapon!=='basic')?'disabled':''}`)}</article>`).join('')}</div><p class="badge">今輪：${M.kit(state).name}${state.aid?' ＋ 思考時間卡':''}。三輪總開支 ${state.spent} 點；餘額保留畀未來需要。</p><div class="actions">${button('器材安排好，開始呢輪','startRound')}</div></section>`;
  else if(phase==='playing')screen.innerHTML=`<section aria-label="訓練場"><div class="hud"><strong>${state.practice?'練習':`第 ${state.round+1}／3 輪`} · ${M.kit(state).name}</strong><span id="time"></span><span id="ammo"></span><strong>${state.credits} 點</strong>${button('暫停','pause')}</div><div class="round-meter" aria-hidden="true"><i id="time-bar"></i></div><div class="range"><canvas id="range-canvas" width="1000" height="460" tabindex="0" data-active="true" aria-label="訓練標靶。1至3揀目標、X或空白射擊、G保護、I查證。亦可用下方文字卡。"></canvas></div><div class="target-list" aria-label="文字標靶（可鍵盤操作）">${state.targets.map(t=>`<button id="target-${t.id}" data-action="select" data-id="${t.id}" aria-pressed="${state.selected===t.id}" ${t.resolved?'disabled':''}><strong>${t.id+1}. ${escape(t.cue)}</strong><span>${t.resolved?(t.correct?'✓ 判斷合適':'已處理，稍後回顧'):t.checked?(t.kind==='check'?escape(t.info):'已核實資料；'+escape(t.why)):t.kind==='check'?'？ 資料未明，先查證':'已提供資料，睇清楚再決定'}</span></button>`).join('')}</div><p class="badge">已選：${escape(state.targets[state.selected].cue)}。${state.targets[state.selected].resolved?'已處理；請揀另一個。':'下面三個操作只影響呢個標靶。'}</p><div class="actions controls">${button('射擊／拒絕 · X','fire')}${button('保護交易 · G','protect')}${button('查證資料 · I','check')}${button('換彈 · R','reload')}</div></section>`;
  else if(phase==='paused')screen.innerHTML=`<section class="panel"><h2>已暫停</h2><p>離開分頁亦會暫停；返回後由你決定幾時繼續。</p><p>餘下 ${state.untimed?'不限時':Math.ceil(state.remaining/1000)+' 秒'}，${state.credits} 點，${state.ammo} 發。</p>${button('繼續訓練','resume')}</section>`;
  else if(['roundResults','practiceResults'].includes(phase))screen.innerHTML=`<section class="panel"><h2>${state.practice?'練習完成':`第 ${state.round+1} 輪回顧`}</h2><p>本輪判斷合適 ${state.targets.filter(t=>t.correct).length}／3。${state.practice?'練習唔會影響正式分數。':`器材支出 ${state.purchases.reduce((n,k)=>n+M.equipment[k].cost,0)} 點；剩 ${state.credits} 點。`}</p>${reviews()}<div class="actions">${button(state.practice?'返回玩法，準備正式開始':state.round===2?'查看總結':'下一輪購買階段','next')}</div></section>`;
  else if(phase==='results'){const z=M.score(state);screen.innerHTML=`<section class="panel"><small>DEBRIEF / 預留下一步</small><h2>決定好，唔一定要買最好。</h2><div class="cards"><div class="card"><h3>金融判斷</h3><strong class="score">${z.judgement}／80</strong><p>${z.correct}／9 個情境處理合適；未查證就猜唔計答對。</p></div><div class="card"><h3>資源保留</h3><strong class="score">${z.resource}／20</strong><p>餘下 ${z.credits}／900 點。器材共用咗 ${state.spent} 點。</p></div><div class="card"><h3>射擊準確率（另計）</h3><strong class="score">${z.accuracy===null?'未射擊':z.accuracy+'%'}</strong><p>${state.hits} 次命中／${state.shots} 次射擊，唔加入金融分數。</p></div></div><p class="score">金融學習分數 ${z.financial}／100</p><p>判斷佔 80 分，保留資源佔 20 分；單靠慳錢唔會完成學習。查證係免費，器材只幫操作，唔會代你判斷。</p><p>為基本需要同未來目標留空間：每次消費前，問總額、到期日同資料係咪已核實。返到阿俊嘅故事，將未到帳收入同手上現金分開，再約定七日後檢視。</p><details><summary>三輪器材開支</summary>${state.history.map(h=>`<p>第 ${h.round+1} 輪：${h.spent} 點 · 判斷 ${h.correct}／3</p>`).join('')}</details><div class="actions">${button('再試一次','retry')}${button('返回阿俊嘅故事','exit')}</div></section>`}
  hud();draw();if(renderedPhase!==phase){screen.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}else if(focused&&$(focused))$(focused).focus({preventScroll:true});renderedPhase=phase;
 }
 function hud(){if($('time'))$('time').textContent=state.untimed?'不限時':`${Math.ceil(state.remaining/1000)} 秒`;
  if($('ammo'))$('ammo').textContent=state.reloadLeft>0?`換彈 ${Math.ceil(state.reloadLeft/100)/10} 秒`:`${state.ammo}／${M.kit(state).ammo} 發`;
  if($('time-bar'))$('time-bar').style.width=(state.untimed?100:state.remaining/(M.ROUND_MS+(state.aid?15000:0))*100)+'%';
 }
 const box=id=>({x:[180,500,820][id],y:210,w:210*M.kit(state).width,h:230});
 function draw(){const c=$('range-canvas');if(!c)return;const ctx=c.getContext('2d');ctx.fillStyle='#183b36';ctx.fillRect(0,0,1000,460);ctx.fillStyle='#416958';ctx.fillRect(0,300,1000,160);ctx.strokeStyle='#749480';ctx.lineWidth=2;
  for(let i=0;i<7;i++){ctx.beginPath();ctx.moveTo(500,260);ctx.lineTo(i*200-100,460);ctx.stroke()}for(let y=320;y<460;y+=38){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1000,y);ctx.stroke()}
  ctx.fillStyle='#b1cbb7';ctx.font='bold 18px system-ui';ctx.fillText('RESOURCE TRAINING / 非人形標靶',24,32);
  for(const t of state.targets){const q=box(t.id);ctx.fillStyle='#162b27';ctx.fillRect(q.x-8,290,16,85);ctx.fillStyle=t.resolved?'#39534a':'#fff8ed';ctx.strokeStyle=state.selected===t.id?'#f1b84d':'#6b8f7c';ctx.lineWidth=state.selected===t.id?6:3;ctx.beginPath();ctx.roundRect(q.x-q.w/2,q.y-q.h/2,q.w,q.h,16);ctx.fill();ctx.stroke();ctx.fillStyle='#173c32';ctx.textAlign='center';ctx.font='bold 50px system-ui';ctx.fillText(t.resolved?(t.correct?'✓':'↻'):t.kind==='check'?'?':t.kind==='reject'?'!':'◇',q.x,193);ctx.font='bold 21px Microsoft JhengHei,system-ui';ctx.fillText('0'+(t.id+1),q.x,235);ctx.font='17px Microsoft JhengHei,system-ui';ctx.fillText(t.resolved?'已處理':t.kind==='check'?'先查證':'睇文字卡決定',q.x,270)}
  ctx.textAlign='left';ctx.strokeStyle='#fff5cd';ctx.lineWidth=2;ctx.beginPath();ctx.arc(aim.x,aim.y,12,0,Math.PI*2);ctx.moveTo(aim.x-24,aim.y);ctx.lineTo(aim.x-5,aim.y);ctx.moveTo(aim.x+5,aim.y);ctx.lineTo(aim.x+24,aim.y);ctx.moveTo(aim.x,aim.y-24);ctx.lineTo(aim.x,aim.y-5);ctx.moveTo(aim.x,aim.y+5);ctx.lineTo(aim.x,aim.y+24);ctx.stroke();c.parentElement.classList.toggle('shot',!state.reduced&&performance.now()<shotUntil);
 }
 function point(e){const r=e.target.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*1000,y:(e.clientY-r.top)/r.height*460}}
 on(screen,'pointermove',e=>{if(e.target.id==='range-canvas'&&state.phase==='playing'){aim=point(e);draw()}});
 on(screen,'pointerdown',e=>{if(e.target.id!=='range-canvas'||state.phase!=='playing')return;e.preventDefault();aim=point(e);const t=state.targets.find(t=>{const q=box(t.id);return !t.resolved&&Math.abs(aim.x-q.x)<=q.w/2&&Math.abs(aim.y-q.y)<=q.h/2});send({type:'fire',id:t?.id??-1,miss:!t});$('range-canvas')?.focus({preventScroll:true})});
 on(document,'click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const type=b.dataset.action;if(type==='exit')return exit();if(type==='select')aim={x:box(Number(b.dataset.id)).x,y:210};send({type,item:b.dataset.item,id:b.dataset.id===undefined?undefined:Number(b.dataset.id)});if(type==='pause')audio?.suspend().catch(()=>{});if(type==='resume'&&!state.muted)audio?.resume().catch(()=>{})});
 on(document,'keydown',e=>{if(e.target.matches('input,select,textarea')||e.repeat)return;if(e.code==='Escape'&&state.phase==='playing'){e.preventDefault();send({type:'pause'});return}if(e.code==='KeyP'&&['playing','paused'].includes(state.phase)){e.preventDefault();send({type:state.phase==='playing'?'pause':'resume'});return}if(state.phase!=='playing')return;
  const mapped={KeyX:'fire',KeyG:'protect',KeyI:'check',KeyR:'reload'};if(mapped[e.code]){e.preventDefault();send({type:mapped[e.code]});return}if(/^[123]$/.test(e.key)){e.preventDefault();const id=Number(e.key)-1;aim={x:box(id).x,y:210};send({type:'select',id});return}
  if(e.target.id==='range-canvas'&&['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code)){e.preventDefault();if(e.code==='Space'){const t=state.targets.find(t=>{const q=box(t.id);return !t.resolved&&Math.abs(aim.x-q.x)<=q.w/2&&Math.abs(aim.y-q.y)<=q.h/2});send({type:'fire',id:t?.id??-1,miss:!t})}else{aim.x=Math.max(0,Math.min(1000,aim.x+(e.code==='ArrowLeft'?-25:e.code==='ArrowRight'?25:0)));aim.y=Math.max(0,Math.min(460,aim.y+(e.code==='ArrowUp'?-25:e.code==='ArrowDown'?25:0)));draw()}}
 });
 on(document,'change',e=>{if(e.target.id==='untimed')send({type:'option',key:'untimed',value:e.target.checked});if(e.target.id==='motion')send({type:'option',key:'reduced',value:e.target.checked});if(e.target.id==='mute'){send({type:'option',key:'muted',value:e.target.checked});if(state.muted)audio?.suspend().catch(()=>{});else sound()}});
 function pause(){if(state.phase==='playing')send({type:'pause'});audio?.suspend().catch(()=>{})}
 on(document,'visibilitychange',()=>{if(document.hidden)pause()});on(window,'blur',pause);on(window,'resize',draw);
 function cleanup(){if(closed)return;closed=true;cancelAnimationFrame(raf);raf=0;events.abort();audio?.close().catch(()=>{});audio=null}
 function exit(){cleanup();if(parent!==window)parent.postMessage({type:'budget-defence-exit'},location.origin);else location.href='../../story/'}
 on($('exit'),'click',exit);on($('retry'),'click',()=>send({type:'retry'}));on(window,'pagehide',cleanup);
 // Read-only snapshot for regression tests and manual diagnostics.
 window.budgetDefenceSnapshot=()=>JSON.parse(JSON.stringify({...state,score:M.score(state),audioState:audio?.state||'not-started'}));render();
})();
